{
  "table": {
    "name": "posts",
    "purpose": "All posts (questions, answers, tag wikis) of a Stack Exchange-style Q&A site about statistics (content: regression, hypothesis-testing, R, Stata, 'degrees of freedom', stats.stackexchange.com duplicate links — i.e., Cross Validated), Feb 2009 – Sep 2014. One row per post, with content, authorship, counts, and lifecycle timestamps."
  },
  "columns": {
    "AcceptedAnswerId": {
      "role": "foreign_key",
      "name": "Accepted answer post ID",
      "description": "For questions, the posts.Id of the answer the asker accepted as best (self-reference to this table; the profiler missed the join, but values fall inside the Id range and are unique). Null for answers and for questions with no accepted answer; only ~16% of rows are populated, consistent with the question share.",
      "status": "resolved"
    },
    "AnswerCount": {
      "role": "numeric",
      "name": "Answer count",
      "description": "Number of answers the question received (0–136). Populated only on questions: non-null share 46.7% exactly matches the PostTypeId=1 share; null on answers and other types.",
      "status": "resolved"
    },
    "Body": {
      "role": "free_text",
      "name": "Post body (HTML)",
      "description": "Full text content of the post as sanitized HTML (question text, answer text, or tag wiki text). Near-unique per row.",
      "status": "resolved"
    },
    "ClosedDate": {
      "role": "date",
      "name": "Closed timestamp",
      "description": "Date-time the question was closed (e.g., duplicate, off-topic); null for open questions, answers, and other post types (~1.8% populated). Format YYYY-MM-DD HH:MM:SS.",
      "status": "resolved"
    },
    "CommentCount": {
      "role": "numeric",
      "name": "Comment count",
      "description": "Number of comments on the post (0–45); consistent with the comments table referencing posts via comments.PostId.",
      "status": "resolved"
    },
    "CommunityOwnedDate": {
      "role": "date",
      "name": "Community wiki conversion timestamp",
      "description": "Date-time the post was converted to community wiki (no single owner); null for the ~97% of posts that are not community wiki.",
      "status": "resolved"
    },
    "CreaionDate": {
      "role": "date",
      "name": "Creation timestamp",
      "description": "Date-time the post was created (column name is a misspelling of CreationDate). Populated on every row; spans 2009-02-02 to 2014-09-14.",
      "status": "resolved"
    },
    "FavoriteCount": {
      "role": "numeric",
      "name": "Favorite (bookmark) count",
      "description": "Number of users who favorited/starred the question (0–233). Recorded only for questions and null for all answers; even among questions it is omitted for most rows in this export (0 also appears 885 times), so null does not strictly mean zero favorites.",
      "status": "resolved"
    },
    "Id": {
      "role": "foreign_key",
      "name": "Post ID (primary key)",
      "description": "Primary key: unique identifier of the post. Referenced by comments.PostId, postHistory.PostId, votes.PostId, postLinks.PostId/RelatedPostId, and (one-to-one) tags.ExcerptPostId and tags.WikiPostId for tag wiki posts.",
      "status": "resolved"
    },
    "LasActivityDate": {
      "role": "date",
      "name": "Last activity timestamp",
      "description": "Date-time of the most recent activity on the post (edit, comment, or new answer). Misspelling of LastActivityDate. Always populated; never earlier than creation.",
      "status": "resolved"
    },
    "LastEditDate": {
      "role": "date",
      "name": "Last edit timestamp",
      "description": "Date-time of the most recent edit to the post; null if the post was never edited (~51% of rows, matching LastEditorUserId's null rate).",
      "status": "resolved"
    },
    "LastEditorDisplayName": {
      "role": "free_text",
      "name": "Last editor display name (orphaned account)",
      "description": "Display name of the last editor, stored only when that editor no longer has a user account — hence anonymized values like 'user10525' (0.5% populated). Null whenever the editor is a normal user (see LastEditorUserId).",
      "status": "resolved"
    },
    "LastEditorUserId": {
      "role": "foreign_key",
      "name": "Last editor user ID",
      "description": "users.Id of the user who made the most recent edit; -1 denotes the community/deleted user; null if the post was never edited.",
      "status": "resolved"
    },
    "OwnerDisplayName": {
      "role": "free_text",
      "name": "Owner display name (orphaned account)",
      "description": "Display name of the post's original author, recorded only when the author no longer has a user account (anonymized 'userNNNNN' names, 2.7% populated); otherwise the owner is identified by OwnerUserId.",
      "status": "resolved"
    },
    "OwnerUserId": {
      "role": "foreign_key",
      "name": "Owner user ID",
      "description": "users.Id of the user who created/owns the post; -1 denotes the community user or a deleted user; null for ~1.5% of rows (owner gone without a preserved display name, e.g., some tag wikis).",
      "status": "resolved"
    },
    "ParentId": {
      "role": "foreign_key",
      "name": "Parent question ID",
      "description": "For answers (PostTypeId=2), the posts.Id of the question the answer belongs to — a self-reference to this table (the profiler's joins to postHistory.Id/comments.Id are spurious). Null for questions and other types; non-null share 51.9% exactly matches the answer share.",
      "status": "resolved"
    },
    "PostTypeId": {
      "role": "category",
      "name": "Post type code",
      "description": "Code classifying the post: 1 = question (42,912 rows — exactly the rows with Title/Tags/ViewCount/AnswerCount), 2 = answer (47,755 rows — exactly the rows with ParentId), 4 = tag wiki excerpt and 5 = tag wiki body (639/640 rows, matching the one-to-one joins to tags.ExcerptPostId / tags.WikiPostId), 6 = moderator nomination post (9 rows), 7 = wiki placeholder. Meanings of 6 and 7 follow the standard Stack Exchange coding and are tentative; the profiler-detected joins to badges/comments/postHistory Ids are small-integer coincidences, not real references.",
      "status": "resolved"
    },
    "Score": {
      "role": "numeric",
      "name": "Vote score",
      "description": "Net score of the post: upvotes minus downvotes (the votes table references posts via votes.PostId). Ranges -19 to +192, median 2.",
      "status": "resolved"
    },
    "Tags": {
      "role": "free_text",
      "name": "Question tags",
      "description": "Angle-bracket-delimited tag names applied to the question, e.g. '<regression><r>'; populated only on questions (null rate matches the non-question share). Tag names correspond to entries in the tags table.",
      "status": "resolved"
    },
    "Title": {
      "role": "free_text",
      "name": "Question title",
      "description": "Title of the question; populated only on questions (null for answers and other post types). Near-unique.",
      "status": "resolved"
    },
    "ViewCount": {
      "role": "numeric",
      "name": "View count",
      "description": "Number of times the question page was viewed (1 to 175,495); populated only on questions.",
      "status": "resolved"
    }
  }
}
